try:
    validate_config({"tracker_id": "NAT", "column_map": {}})
except ValueError as err:
    text = str(err)
    assert "type_map" in text and "max_null_weights" in text, text
else:
    raise AssertionError("no ValueError")

base = {"tracker_id": "NAT", "column_map": {}, "type_map": {}, "merge_keys": ["k"],
        "weight_sum_min": 1.0, "weight_sum_max": 10.0, "max_null_weights": 0}
for change in ({"merge_keys": []}, {"weight_sum_min": 20.0}):
    try:
        validate_config({**base, **change})
    except ValueError:
        continue
    raise AssertionError(f"accepted {change}")

try:
    enforce([{"check_name": "null_weights", "status": "FAIL", "severity": "CRITICAL"},
             {"check_name": "cast_failures", "status": "WARN", "severity": "WARN"},
             {"check_name": "key_uniqueness", "status": "FAIL", "severity": "CRITICAL"}])
except RuntimeError as err:
    assert "null_weights" in str(err) and "key_uniqueness" in str(err), str(err)
    assert "cast_failures" not in str(err)
else:
    raise AssertionError("no RuntimeError")

